// Decides which pending orders get a payment reminder, which are auto-cancelled,
// and which need a human. Reads the Orders rows from the previous node.
// ---- settings -------------------------------------------------------------
const REMIND_AFTER_HOURS = 6;      // send one reminder once an unpaid order is this old
const CANCEL_AFTER_HOURS = 48;     // cancel if still unpaid this long after ordering
const QUIET_START = 22;            // no customer messages from 22:00 ...
const QUIET_END = 9;               // ... until 09:00 (Dhaka time)
const MAX_PER_RUN = 50;            // stay well inside WhatsApp rate limits
const PAY_TO = 'YOUR_BKASH_NUMBER'; // shown in the reminder (bKash/Nagad merchant or personal number)
const DHAKA_OFFSET_MIN = 360;      // Asia/Dhaka is UTC+6 all year (no DST)
// ---------------------------------------------------------------------------

const now = Date.now();
const dhakaHour = new Date(now + DHAKA_OFFSET_MIN * 60000).getUTCHours();
const quiet = QUIET_START > QUIET_END
  ? dhakaHour >= QUIET_START || dhakaHour < QUIET_END
  : dhakaHour >= QUIET_START && dhakaHour < QUIET_END;

// Accepts ISO timestamps (written by whatsapp-order-bot), "YYYY-MM-DD HH:mm" or
// "DD/MM/YYYY HH:mm" in Dhaka time, and Google Sheets serial day numbers.
const parseDate = (v) => {
  if (v === null || v === undefined || v === '') return NaN;
  if (typeof v === 'number' || /^\d+(\.\d+)?$/.test(String(v).trim())) {
    return Math.round((Number(v) - 25569) * 86400000) - DHAKA_OFFSET_MIN * 60000;
  }
  const s = String(v).trim();
  if (/[zZ]|[+-]\d\d:?\d\d$/.test(s)) return Date.parse(s);
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2}))?/);
  let y, mo, d, h, mi;
  if (m) [, y, mo, d, h, mi] = m;
  else if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?/))) [, d, mo, y, h, mi] = m;
  else return NaN;
  return Date.UTC(+y, +mo - 1, +d, +(h || 0), +(mi || 0)) - DHAKA_OFFSET_MIN * 60000;
};
const toIntl = (p) => {
  const d = String(p || '').replace(/\D/g, '');
  if (/^01\d{9}$/.test(d)) return '88' + d;
  return /^8801\d{9}$/.test(d) ? d : '';
};

const out = [];
for (const { json: o } of $input.all()) {
  if (!o || !o.OrderID) continue;
  if (String(o.Status || '').trim().toLowerCase() !== 'pending') continue;
  if (String(o.TrxID || '').trim()) continue; // a payment is already linked
  const placed = parseDate(o.Date);
  const base = { orderId: String(o.OrderID), name: o.Name || '', total: o.Total ?? '' };
  if (Number.isNaN(placed)) {
    out.push({ ...base, action: 'review', note: `Order ${o.OrderID}: unreadable Date "${o.Date}", check the sheet.` });
    continue;
  }
  const ageHours = (now - placed) / 3600000;
  const customerWa = toIntl(o.WhatsApp || o.Phone);
  const reminded = String(o.ReminderSentAt || '').trim() !== '';

  if (ageHours >= CANCEL_AFTER_HOURS) {
    if (reminded) {
      out.push({ ...base, action: 'cancel', ageHours: Math.floor(ageHours),
        note: `Order ${o.OrderID} (Tk ${base.total}) auto-cancelled: unpaid after ${Math.floor(ageHours)} h and one reminder.` });
    } else {
      out.push({ ...base, action: 'review', ageHours: Math.floor(ageHours),
        note: `Order ${o.OrderID} (Tk ${base.total}) unpaid for ${Math.floor(ageHours)} h but no reminder was sent` +
          (customerWa ? '.' : ' (no valid WhatsApp number).') + ' Please follow up by phone.' });
    }
  } else if (ageHours >= REMIND_AFTER_HOURS && !reminded && customerWa && !quiet) {
    out.push({ ...base, action: 'remind', customerWa, payTo: PAY_TO, ageHours: Math.floor(ageHours),
      sentAt: new Date(now).toISOString() });
  }
}
// Reminders first so a busy run never starves them behind cancellations.
const rank = { remind: 0, cancel: 1, review: 2 };
out.sort((a, b) => rank[a.action] - rank[b.action]);
return out.slice(0, MAX_PER_RUN).map((json) => ({ json }));
